<div class="page-actions"><div><p class="mb-0">CRM pipeline dengan drag & drop status.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#leadModal"><i class="bi bi-plus-lg"></i> New Lead</button></div>
<div class="lead-board" id="leadBoard">
<?php foreach($statuses as $status): ?><section class="lead-column" data-status="<?= e($status) ?>"><header><strong><?= e($status) ?></strong><span><?= count($board[$status]) ?></span></header><div class="lead-dropzone"><?php foreach($board[$status] as $lead): ?><article class="lead-card" draggable="true" data-lead-id="<?= $lead['id'] ?>"><div class="d-flex justify-content-between gap-2"><strong><?= e($lead['customer_name']) ?></strong><small><?= e($lead['lead_number']) ?></small></div><span><?= e($lead['company']?:$lead['service_interest']?:'Lead') ?></span><?php if((float)$lead['estimated_value']>0): ?><b><?= e(money($lead['estimated_value'])) ?></b><?php endif; ?><small><?= $lead['follow_up_date']?'Follow-up '.$lead['follow_up_date']:'No follow-up date' ?></small><div class="d-flex gap-1 mt-2"><?php if($status!=='Won'&&$status!=='Lost'): ?><button class="btn btn-sm btn-outline-success ajax-action" data-url="<?= url('/leads/'.$lead['id'].'/convert') ?>">Convert</button><?php endif; ?></div></article><?php endforeach; ?></div></section><?php endforeach; ?>
</div>
<div class="modal fade" id="leadModal"><div class="modal-dialog modal-lg"><form class="modal-content ajax-form" method="post" action="<?= url('/leads') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Lead</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><div class="col-md-6"><label class="form-label">Customer Name</label><input class="form-control" name="customer_name" required></div><div class="col-md-6"><label class="form-label">Company</label><input class="form-control" name="company"></div><div class="col-md-4"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="col-md-4"><label class="form-label">WhatsApp</label><input class="form-control" name="whatsapp"></div><div class="col-md-4"><label class="form-label">Email</label><input class="form-control" type="email" name="email"></div><div class="col-md-4"><label class="form-label">Source</label><input class="form-control" name="source"></div><div class="col-md-4"><label class="form-label">Service Interest</label><input class="form-control" name="service_interest"></div><div class="col-md-4"><label class="form-label">Estimated Value</label><input class="form-control" type="number" step="0.01" name="estimated_value"></div><div class="col-md-6"><label class="form-label">Follow-up</label><input class="form-control" type="date" name="follow_up_date"></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach($statuses as $s): ?><option><?= e($s) ?></option><?php endforeach; ?></select></div><div class="col-12"><textarea class="form-control" name="notes" placeholder="Notes"></textarea></div></div><div class="modal-footer"><button class="btn btn-primary">Save Lead</button></div></form></div></div>
